// H1 [happy_path]: Valid_return_is_accepted_refunded_and_restocked
{
    var handler = new ReturnsHandler();
    var order = new Order
    {
        Reference = "RET-H1",
        Lines =
        {
            new OrderLine { Sku = "SKU-H1", Quantity = 2, UnitPrice = 20m }
        }
    };
    var customer = new Customer { Tier = CustomerTier.Standard };
    
    var initialIsReturnable = handler.IsReturnable(order);
    var computedRefund = handler.ComputeRefund(order);
    var processResult = handler.ProcessReturn(order, customer);
    var isReturnableAfterProcessing = handler.IsReturnable(order);
    var restockedQuantity = handler.Restock(order);
    
    Check.True(initialIsReturnable);
    Check.Equal(10m, computedRefund);
    Check.Equal("accepted", processResult);
    Check.False(isReturnableAfterProcessing);
    Check.Equal(2, restockedQuantity);
